insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('1aa02b46-ae84-479d-9ecc-da1cfd50fa9a','zh-tw','bombardiro-crocodilo','轟炸機鱷魚(Bombardiro Crocodilo)','AI生成的轟炸機與鱷魚合體角色，義式腦腐代表角色之一','這是一隻轟炸機身軀配上鱷魚臉孔的AI生成角色，搭配義大利語旁白，是擁有詭異世界觀的「腦腐(Brainrot)」角色系列之一。內容延伸出與Tralalero Tralala等其他腦腐角色交織的世界觀影片。在韓國10多歲、20多歲族群之間，也被當作「看不懂但很好笑」的迷因分享。','2025年初以AI圖像、語音生成工具製作而成的義大利語腦腐角色系列之一，透過TikTok擴散。','分享無意義卻好笑的AI迷因時使用',null,array['Bombardino Crocodilo','봄바르디로 크로코딜로(Bombardiro Crocodilo)'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

