-- pxuqzg4s  063ce340-c496-48be-a88c-5cc5d5e370bd  「你也？我也？YANADOO」
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('063ce340-c496-48be-a88c-5cc5d5e370bd','zh-tw','neodu-nadu-yanadu','「你也？我也？YANADOO」','英語教育廣告詞因網路實況主沉著男(침착맨)的模仿再度爆紅的案例','線上英語教育品牌「YANADOO(야나두)」的廣告詞「你也？我也？YANADOO」原本是2010年代中期推出的廣告文案，但實況主沉著男在直播中頻繁模仿這句話，使其於2019年底在Twitch、網路社群上再度像流行語一樣被使用。也被縮寫成「ㄴㄷ?」、「ㅇㄴㄷ」等初聲形式使用。','YANADOO廣告詞，經沉著男模仿後再度流行(2019年)','半開玩笑地邀請對方一起做某事時使用',null,array['YANADOO','沉著男 YANADOO','너두 나두 야나두'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

-- by5gkxee  d574e4cd-eaeb-453a-9994-020e2b0a6f7d  三兄弟蘿蔔頭(갈갈이 삼형제)
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('d574e4cd-eaeb-453a-9994-020e2b0a6f7d','zh-tw','galgari-three-brothers','三兄弟蘿蔔頭(갈갈이 삼형제)','1999~2003年《Gag Concert》人氣單元及其流行語「請給我蘿蔔」','朴俊炯、鄭鍾哲、李昇煥主演的《Gag Concert》單元「갈갈이 삼형제(三兄弟蘿蔔頭)」，以流行語「請給我蘿蔔！」掀起高人氣，帶領《Gag Concert》走向全盛期。直到2003年7月完結為止，這個單元培養出以「蘿蔔頭家族」之名走紅的多位喜劇演員。','KBS《Gag Concert》的這個單元，原本是以外國影集《緊急救援911》的韓語配音惡搞版本、名為「聲音模仿男孩(패러디 보이스)」起家的。2001年9月首播時，角色為了救溺水者而做船、用牙齒挖蘿蔔內部的橋段意外大受歡迎，於是在結尾反覆呈現這個橋段重新編排單元內容，名稱也改為「갈갈이 삼형제(三兄弟蘿蔔頭)」。朴俊炯、鄭鍾哲、李昇煥主演，留下「請給我蘿蔔」這句流行語，播出至2003年7月，成為《Gag Concert》草創期的代表單元。','想機智地拜託別人某件事時，可以用「請給我蘿蔔」的方式惡搞',null,array['請給我蘿蔔','蘿蔔頭家族','갈갈이 삼형제'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

-- q832kx9m  dfef04c8-3e40-4d14-a57e-5920278584ed  紅綠燈顏色迷因
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('dfef04c8-3e40-4d14-a57e-5920278584ed','zh-tw','traffic-light-color-meme','紅綠燈顏色迷因','李武鎮2021年熱門歌曲〈紅綠燈〉副歌顏色歌詞，被套用於各種情境的模仿迷因','李武鎮於2021年5月14日發行的首張單曲〈紅綠燈〉，是一首把成年後青春的心情比喻成紅綠燈的歌曲，當年下半年爆紅。副歌歌詞「紅色、藍色，之間的3秒」，因能對應到各種可用兩種對比顏色表現的情境(如股市走勢圖等)，被廣泛套用惡搞，成為一種迷因。','李武鎮首張單曲〈紅綠燈〉(2021.5.14發行)歌詞','想表達像紅與藍那樣對比的兩種情況時，很適合使用',null,array['李武鎮 紅綠燈迷因','신호등 색깔 밈'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

-- t2fpqhcs  8c30c56f-ee28-4706-b85d-8570bc2e5183  테스형(蘇格拉底老兄)
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('8c30c56f-ee28-4706-b85d-8570bc2e5183','zh-tw','tes-hyeong-socrates','테스형(蘇格拉底老兄)','羅勳兒在2020年中秋特別公演演唱的歌曲中，稱呼蘇格拉底的暱稱成為萬用流行語的案例','歌王羅勳兒於2020年8月發行的正規9輯主打歌〈테스형(蘇格拉底老兄)！〉，是一首彷彿對著蘇格拉底傾訴對父親思念之情的歌曲。他在2020年中秋特別公演「大韓民國Again羅勳兒」上熱唱這首歌後爆紅，副歌中質問世界為何如此的歌詞，被套用在各種情境中惡搞，成為萬用流行語。','羅勳兒正規9輯《九個故事》主打歌〈테스형(蘇格拉底老兄)！〉(2020.8.20發行)，2020中秋特別公演「大韓民國Again羅勳兒」','把「蘇格拉底老兄」換成別的對象，用來抱怨世事不順時很好用',null,array['테스형!','아 테스형','테스형'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

-- 47exgvcf  9c2d7b1b-23fe-4870-9b6d-83fc78d7d32e  李漢碩記者模擬跳塔訓練
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9c2d7b1b-23fe-4870-9b6d-83fc78d7d32e','zh-tw','reporter-lee-han-seok-tower-training','李漢碩記者模擬跳塔訓練','SBS李漢碩記者在特戰部隊軍營體驗中，於11公尺模擬跳塔發出的怪異慘叫成為經典惡搞素材','2011年8月，SBS李漢碩記者為拍攝陸軍特殊戰司令部特戰營(軍營體驗)報導，挑戰11公尺高的模擬跳塔訓練，當時發出的獨特沙啞慘叫聲引發話題。這段影片自2011年8月8日起，在DCInside合成惡搞素材版被廣泛用作各種惡搞素材，晉升為經典梗。之後與朴大基、郭承圭等其他記者的影片一起被拿來剪輯，帶動了所謂「記者迷因圖」的風潮。','2011年8月SBS新聞特戰營體驗報導影片，於DCInside合成惡搞素材版開始流行','用來表達荒謬又好笑的反應時，可以廣泛使用',null,array['李漢碩記者 特戰部隊體驗','SBS 李漢碩記者','特戰營慘叫','이한석 기자 모형탑 훈련'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

-- pwb8uaxr  6a94ca15-7faa-419a-b743-2516e9ce7068  KTF Na「爸，我是誰？我也不太清楚」
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('6a94ca15-7faa-419a-b743-2516e9ce7068','zh-tw','ktf-na-i-dont-really-know','KTF Na「爸，我是誰？我也不太清楚」','為象徵免費通話而即興演出的KTF Na廣告父子對話台詞','2000年5月，KTF推出品牌Na時，發表了一支廣告，內容是兒子問「爸，我是誰？」，父親則回答「我也不太清楚」。據悉，為了強調代表免費的數字0，父親即興做出用手比畫圓形頭部的動作。演員朴龍鎮與金相庚主演，被譽為當代最賣座的廣告之一。','2000年5月KTF Na電視廣告，朴龍鎮、金相庚主演','想含糊帶過「不太清楚」時，可以引用「我也不太清楚」',null,array['我也不太清楚','KTF Na 아버지 나는 누구예요 나도 잘 몰러'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

-- jjuvahfy  edd7bd1d-569d-4885-82c3-37110282fee6  PSY〈Champion〉
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('edd7bd1d-569d-4885-82c3-37110282fee6','zh-tw','psy-champion','PSY〈Champion〉','受2002世界盃紅魔啦啦隊啟發創作的PSY健康向應援歌','PSY在2002年韓日世界盃期間，看到首爾廣場上紅魔啦啦隊的應援場面獲得靈感創作而成，取樣自哈羅德·法特梅爾(Harold Faltermeyer)的〈Axel F〉。2002年9月發行後大受歡迎，讓PSY獲得「健康玩樂歌手」的新形象。','受2002世界盃紅魔啦啦隊應援現場啟發作曲，2002年9月19日發行','至今仍常在炒熱應援歌、派對氣氛時被召喚使用',null,array['Champion','2002世界盃 冠軍','싸이 - 챔피언'],'[{"text": "今天聚餐要炒熱氣氛就放Champion吧", "situation": "聚餐群組"}, {"text": "這個應援根本是Champion等級的氣勢", "situation": "社群留言"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

-- tsv8ufqq  c91ddd65-5ef0-473d-b01c-7d1c3512c4c9  江南Style
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('c91ddd65-5ef0-473d-b01c-7d1c3512c4c9','zh-tw','gangnam-style','江南Style','隨PSY騎馬舞紅遍全球的2012年最大熱門挑戰','PSY於2012年7月發行的〈江南Style〉，搭配編舞師李朱善創作的「騎馬舞」，透過YouTube在全球擴散。曾登上艾倫秀等美國電視節目，成為韓國大眾歌曲史上首度在30多個國家排行榜登頂的作品。','2012年7月PSY正規6輯主打歌，編舞師李朱善的騎馬舞','用於歡樂氣氛或挑戰引用都很安全通用',null,array['騎馬舞','歐爸江南Style','강남스타일'],'[{"text": "今天聚餐就用江南Style騎馬舞收尾吧", "situation": "聚餐群組"}, {"text": "這個挑戰根本是江南Style等級的擴散力", "situation": "社群留言"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

-- rnyv6jwt  70ee6329-57be-4547-bd14-a833bbc3dbfa  「任意歌」挑戰
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('70ee6329-57be-4547-bd14-a833bbc3dbfa','zh-tw','any-song-challenge','「任意歌」挑戰','配合ZICO〈任意歌〉甩手臂的簡單舞步挑戰','2020年1月ZICO發行新曲〈任意歌(아무노래)〉時，與華莎一起拍攝挑戰影片並上傳，掀起熱潮。聳肩、甩手臂等簡單動作讓男女老少都能輕鬆跟跳，迅速擴散開來。眾多藝人與網紅參與其中，被譽為K-pop挑戰文化的起點。','ZICO在2020年1月13日〈任意歌〉發行前夕，與華莎一起拍攝並上傳到社群平台的影片為起點','談論挑戰文化時，作為簡單挑戰的代名詞被提及',null,array['Any Song Challenge','ZICO 任意歌挑戰','아무노래 챌린지'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

-- jcdupe54  9f480f20-5b12-40b4-b3bb-513a4f0f8c39  巴茲解放戰爭
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9f480f20-5b12-40b4-b3bb-513a4f0f8c39','zh-tw','batz-liberation-war','巴茲解放戰爭','2004年玩家聯合對抗《天堂2》伺服器獨裁統治的戰爭','2004年6月至2008年3月間，在線上遊戲《天堂2》的「巴茲」伺服器上，一般玩家聯合起來對抗掌控該伺服器的DK血盟獨裁統治的事件，超過20萬人參與，被稱為「線上首場市民革命」，也對遊戲奇幻小說的固定套路產生了深遠影響。','2004年6月，掌控《天堂2》巴茲伺服器的「龍騎士(DK)血盟」調高低等級玩家必需品的稅率等，強化壟斷式經營，多數玩家聯合組成的「巴茲聯合軍」因此組成並展開對抗。戰爭持續至2008年3月，據悉累計超過20萬人次參與，論壇上湧入大量通報戰況的貼文，一般媒體也將此比喻為「線上市民革命」加以報導。之後被改編成論文、展覽、文學等各種內容，成為韓國線上遊戲史上數一數二的重大事件。','作為線上遊戲社群文化案例被提及',null,array['바츠 해방전쟁'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;

